<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';import { Building2, RefreshCw, ShieldCheck, Truck, TriangleAlert } from 'lucide-vue-next';import { ElMessage } from 'element-plus';import { api } from '../api';import AnalyticsChart from '../components/AnalyticsChart.vue';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';import type { SafetyProfile } from '../types';
const session=useSessionStore(),loading=ref(false),items=ref<SafetyProfile[]>([]),selected=ref<SafetyProfile|null>(null),drawer=ref(false),q=ref('');const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');function radar(profile:SafetyProfile){const d=profile.dimensions;return{radar:{radius:'62%',indicator:[{name:'安全表现',max:100},{name:'合规表现',max:100},{name:'运行表现',max:100},{name:'在线稳定',max:100},{name:'应急响应',max:100},{name:'自主运行',max:100}]},series:[{type:'radar',data:d?[{value:[d.safety,d.compliance,d.operation,d.onlineStability,d.emergencyResponse,d.autonomy],areaStyle:{color:'rgba(49,95,145,.2)'},lineStyle:{color:'#315f91'},itemStyle:{color:'#315f91'}}]:[]} ]}}async function load(){loading.value=true;try{const p=new URLSearchParams();if(q.value)p.set('q',q.value);const r=await api<{items:SafetyProfile[]}>(`/analytics/profiles?${p}`);items.value=r.items;if(isEnterprise.value&&items.value[0])selected.value=items.value[0]}catch(e){ElMessage.error(e instanceof Error?e.message:'安全画像加载失败')}finally{loading.value=false}}function open(x:SafetyProfile){selected.value=x;drawer.value=true}const riskText=(x:SafetyProfile)=>x.evaluation?.riskLevel==='CRITICAL'?'重大风险':x.evaluation?.riskLevel==='HIGH'?'较高风险':x.evaluation?.riskLevel==='MEDIUM'?'一般风险':'低风险';onMounted(load);
</script>
<template><PageHeader :title="isEnterprise?'企业安全画像':'企业安全画像'" description="汇聚评价、车辆、告警、事故、违规与联网数据，形成可解释的风险特征。"><el-input v-if="!isEnterprise" v-model="q" clearable placeholder="搜索企业" style="width:220px" @keyup.enter="load"/><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button></PageHeader><section v-if="isEnterprise&&selected" class="profile-hero" v-loading="loading"><div class="profile-identity"><span class="profile-logo"><Building2/></span><div><small>{{selected.enterprise.businessNo}}</small><h2>{{selected.enterprise.name}}</h2><p>法定代表人 {{selected.enterprise.legalRepresentative}} · 安全联系人 {{selected.enterprise.contactName}} {{selected.enterprise.contactPhone}}</p><div><el-tag v-for="tag in selected.tags" :key="tag" effect="plain">{{tag}}</el-tag></div></div><aside><span>本期评价</span><strong>{{selected.evaluation?.totalScore??'—'}}</strong><el-tag :type="selected.evaluation?.grade==='A'?'success':selected.evaluation?.grade==='B'?'primary':'warning'">{{selected.evaluation?.grade??'—'}} 级 · {{riskText(selected)}}</el-tag></aside></div><div class="profile-body"><article class="phase6-panel"><header><div><strong>安全能力雷达</strong><span>六维数据归一化至 100 分</span></div></header><AnalyticsChart :option="radar(selected)" height="360px"/></article><article class="phase6-panel"><header><div><strong>监管事实摘要</strong><span>平台全周期累计数据</span></div></header><div class="profile-facts"><span><Truck/><b>{{selected.metrics.vehicleCount}}</b><small>备案车辆</small></span><span><ShieldCheck/><b>{{selected.metrics.alerts}}</b><small>安全告警</small></span><span><TriangleAlert/><b>{{selected.metrics.accidents}}</b><small>事故记录</small></span><span><TriangleAlert/><b>{{selected.metrics.violations}}</b><small>违规记录</small></span></div><dl class="analysis-dl"><dt>本期结论</dt><dd>{{selected.evaluation?.conclusion??'尚未发布企业评价'}}</dd><dt>累计运营里程</dt><dd>{{selected.metrics.mileage}} km</dd><dt>画像更新时间</dt><dd>{{selected.evaluation?.publishedAt?new Date(selected.evaluation.publishedAt).toLocaleString('zh-CN'):'随监管数据实时更新'}}</dd></dl></article></div></section><section v-else-if="!isEnterprise" class="profile-grid" v-loading="loading"><button v-for="x in items" :key="x.enterprise.id" @click="open(x)"><header><span><Building2/></span><el-tag :type="x.evaluation?.riskLevel==='HIGH'||x.evaluation?.riskLevel==='CRITICAL'?'danger':x.evaluation?.riskLevel==='MEDIUM'?'warning':'success'">{{riskText(x)}}</el-tag></header><strong>{{x.enterprise.name}}</strong><small>{{x.enterprise.businessNo}}</small><div class="profile-score"><b>{{x.evaluation?.totalScore??'—'}}</b><span>{{x.evaluation?.grade??'—'}} 级</span></div><p><span>{{x.metrics.vehicleCount}} 辆车</span><span>{{x.metrics.alerts}} 告警</span><span>{{x.metrics.accidents}} 事故</span><span>{{x.metrics.violations}} 违规</span></p><footer><el-tag v-for="tag in x.tags.slice(0,2)" :key="tag" size="small" effect="plain">{{tag}}</el-tag></footer></button><el-empty v-if="!items.length" description="暂无企业画像"/></section><el-drawer v-model="drawer" title="企业安全画像" size="720px"><template v-if="selected"><div class="drawer-profile-title"><div><strong>{{selected.enterprise.name}}</strong><span>{{selected.enterprise.businessNo}}</span></div><b>{{selected.evaluation?.totalScore??'—'}} 分</b></div><AnalyticsChart :option="radar(selected)" height="300px"/><div class="profile-facts"><span><Truck/><b>{{selected.metrics.vehicleCount}}</b><small>备案车辆</small></span><span><ShieldCheck/><b>{{selected.metrics.alerts}}</b><small>安全告警</small></span><span><TriangleAlert/><b>{{selected.metrics.accidents}}</b><small>事故</small></span><span><TriangleAlert/><b>{{selected.metrics.violations}}</b><small>违规</small></span></div><p class="conclusion-box">{{selected.evaluation?.conclusion??'尚未发布评价结果'}}</p></template></el-drawer></template>
